"""CCAR-F part B1: flashcards and questions for Domain 3 (Claude Code Configuration and Workflows),
Domain 4 (Prompt Engineering and Structured Output) and Domain 5 (Context Management and Reliability).

Written against the official Claude Certified Architect - Foundations exam guide (version 1.0,
effective July 2026): task statements 3.1-3.6 (20%), 4.1-4.6 (20%) and 5.1-5.6 (15%). Product facts were
checked against the current Claude Code, Claude API and Agent SDK documentation (October 2026).
Writer B2 fills data/ccarf_b2.py (lessons, games, case studies, cheat sheet). Part B ids start at 1001.
"""


def _fc(i, cat, front, back, detail):
    return {'id': i, 'cat': cat, 'front': front, 'back': back, 'detail': detail}


def _mc(i, cat, question, options, correct, explanation, why=None):
    q = {'id': i, 'cat': cat, 'type': 'mc', 'question': question, 'options': options, 'correct': correct, 'explanation': explanation}
    if why:
        q['whyTested'] = why
    return q


def _ms(i, cat, question, options, correct, explanation, why=None):
    q = {'id': i, 'cat': cat, 'type': 'ms', 'question': question, 'options': options, 'correct': correct, 'explanation': explanation}
    if why:
        q['whyTested'] = why
    return q


def _tf(i, cat, question, answer, explanation, why=None):
    q = {'id': i, 'cat': cat, 'type': 'tf', 'question': question, 'answer': answer, 'explanation': explanation}
    if why:
        q['whyTested'] = why
    return q


